mapper.select:
SELECT id, purpose, username, email, phone, code_hash, expire_time, used_time, status, create_time, update_time
FROM t_email_verification_code
WHERE username = #{username}
  AND email = #{email}
  AND phone = #{phone}
  AND purpose = #{purpose}
  AND used_time IS NULL
  AND status = 'ACTIVE'
ORDER BY create_time DESC
LIMIT 1

mapper.update:
UPDATE t_email_verification_code
SET status = 'INVALID', update_time = #{updateTime}
WHERE email = #{email}
  AND purpose = #{purpose}
  AND used_time IS NULL
  AND status = 'ACTIVE'

UPDATE t_email_verification_code
SET status = 'USED', used_time = #{usedTime}, update_time = #{usedTime}
WHERE id = #{id}
  AND used_time IS NULL
  AND status = 'ACTIVE'

UPDATE t_email_verification_code
SET status = 'INVALID', update_time = #{updateTime}
WHERE id = #{id}
  AND used_time IS NULL
  AND status = 'ACTIVE'
